  }

  if (visited.has(value)) {
    return visited.get(value);
  }

  const result = Array.isArray(value) ? [] : {};
  visited.set(value, result);

  for (const key of Object.keys(value)) {
    result[key] = deepClone(value[key], visited);
  }

  return result;
}

